@dataclass(frozen=True)
class Control:
    id: str
    area: str
    title: str
    regulation: str
    applies_to: tuple[str, ...]          # домены; "*" — любой финтех-проект
    patterns: tuple[str, ...]            # регэкспы-признаки покрытия
    severity: str                        # серьёзность, если контроль отсутствует
    category: str                        # security | compliance | fintech
    question: str
    why: str
    recommendation: str
    suggested_text: str
    answer_options: tuple[str, ...] = field(default_factory=tuple)   # первый — рекомендуемый
    addressee: str = "ИБ / Архитектор"
    min_hits_covered: int = 2            # сколько разных признаков нужно для «покрыто»
    default_assumption: str = ""         # что закладываем в ТЗ v2, если ответа не будет


