CONTROLS_BY_ID = {c.id: c for c in CONTROLS}


def applicable_controls(domains: list[str]) -> list[Control]:
    ds = set(domains)
    return [c for c in CONTROLS if "*" in c.applies_to or ds.intersection(c.applies_to)]
